const raw = String($json.observations_json || '').trim();
let input;
try { input = JSON.parse(raw); } catch { throw new Error('invalid_competitive_observations_json'); }
if (!Array.isArray(input) || input.length < 1 || input.length > 50) throw new Error('competitive_observation_batch_size_invalid');

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const timezone = /(Z|[+-]\d{2}:\d{2})$/i;
const allowedTypes = new Set(['PRODUCT_LAUNCH','PRICE','PROMOTION','STOCK','MERCHANDISING','CRO','SEO','CONTENT','SOCIAL','CHANNEL','REVIEW','CUSTOMER_PAIN','OTHER']);
const allowedKeys = new Set(['source_id','dedupe_key','observation_type','subject','facts','evidence','confidence','relevance','observed_at','source_published_at']);
const seen = new Set();

const observations = input.map((item, index) => {
  if (!item || typeof item !== 'object' || Array.isArray(item)) throw new Error('invalid_competitive_observation_' + index);
  for (const key of Object.keys(item)) {
    if (!allowedKeys.has(key)) throw new Error('unexpected_competitive_observation_field_' + key);
  }

  const sourceId = String(item.source_id || '').trim();
  if (!uuid.test(sourceId)) throw new Error('invalid_competitive_source_id_' + index);

  const dedupeKey = String(item.dedupe_key || '').trim();
  if (!dedupeKey || dedupeKey.length > 255) throw new Error('invalid_competitive_dedupe_key_' + index);
  if (seen.has(dedupeKey)) throw new Error('duplicate_competitive_dedupe_key_' + index);
  seen.add(dedupeKey);

  const observationType = String(item.observation_type || '').trim().toUpperCase();
  if (!allowedTypes.has(observationType)) throw new Error('invalid_competitive_observation_type_' + index);

  const subject = String(item.subject || '').trim();
  if (!subject || subject.length > 500) throw new Error('invalid_competitive_subject_' + index);

  const facts = item.facts === undefined ? {} : item.facts;
  if (!facts || typeof facts !== 'object' || Array.isArray(facts)) throw new Error('invalid_competitive_facts_' + index);

  const evidence = item.evidence === undefined ? [] : item.evidence;
  if (!Array.isArray(evidence) || evidence.length > 50 || evidence.some((entry) => !entry || typeof entry !== 'object' || Array.isArray(entry))) {
    throw new Error('invalid_competitive_evidence_' + index);
  }

  const confidence = Number(item.confidence);
  const relevance = Number(item.relevance);
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new Error('invalid_competitive_confidence_' + index);
  if (!Number.isFinite(relevance) || relevance < 0 || relevance > 1) throw new Error('invalid_competitive_relevance_' + index);

  const observedRaw = String(item.observed_at || '').trim();
  if (!timezone.test(observedRaw) || !Number.isFinite(Date.parse(observedRaw))) throw new Error('invalid_competitive_observed_at_' + index);
  const observedAt = new Date(observedRaw);

  let sourcePublishedAt = null;
  if (item.source_published_at !== undefined && item.source_published_at !== null && String(item.source_published_at).trim()) {
    const publishedRaw = String(item.source_published_at).trim();
    if (!timezone.test(publishedRaw) || !Number.isFinite(Date.parse(publishedRaw))) throw new Error('invalid_competitive_source_published_at_' + index);
    const publishedAt = new Date(publishedRaw);
    if (publishedAt.getTime() > observedAt.getTime() + 5 * 60 * 1000) throw new Error('competitive_source_published_after_observed_' + index);
    sourcePublishedAt = publishedAt.toISOString();
  }

  return {
    source_id: sourceId,
    dedupe_key: dedupeKey,
    observation_type: observationType,
    subject,
    facts,
    evidence,
    confidence: Number(confidence.toFixed(5)),
    relevance: Number(relevance.toFixed(5)),
    observed_at: observedAt.toISOString(),
    source_published_at: sourcePublishedAt
  };
});

const executionId = String($execution.id || '').trim();
if (!executionId) throw new Error('missing_competitive_execution_id');

const body = JSON.stringify({
  workflow_key: 'competitive-intelligence',
  workflow_version: 'v1',
  execution_id: executionId.slice(0,255),
  observations
});

return [{json:{
  shadow_body: body,
  expected_count: observations.length,
  dedupe_keys: observations.map((item) => item.dedupe_key).sort()
}}];

const crypto = require('crypto');
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const receiptUrl = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('automation_command_secret_not_configured');
if (!/\/api\/v1\/automation\/control\/receipt$/.test(receiptUrl)) throw new Error('automation_control_receipt_url_invalid');

const body = String($json.shadow_body || '');
if (!body) throw new Error('competitive_shadow_body_missing');
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body, 'utf8').digest('hex');
const shadowUrl = receiptUrl.replace(/\/api\/v1\/automation\/control\/receipt$/, '/api/v1/automation/competitive-intelligence/observations/shadow');
const stableKeys = Array.isArray($json.dedupe_keys) ? [...$json.dedupe_keys].sort() : [];
const receiptKey = 'competitive-intelligence-shadow:' + crypto.createHash('sha256').update(JSON.stringify(stableKeys), 'utf8').digest('hex');

return [{json:{
  shadow_url: shadowUrl,
  shadow_body: body,
  shadow_timestamp: timestamp,
  shadow_signature: signature,
  expected_count: Number($json.expected_count || 0),
  dedupe_keys: stableKeys,
  receipt_key: receiptKey
}}];

const response = $input.first().json || {};
const statusCode = Number(response.statusCode || 0);
if (statusCode < 200 || statusCode >= 300) throw new Error('competitive_shadow_http_' + statusCode);

const body = response.body || {};
if (body.accepted !== true) throw new Error('competitive_shadow_not_accepted');
if (String(body.mode || '') !== 'SHADOW') throw new Error('competitive_shadow_mode_invalid');
if (body.external_action_taken !== false) throw new Error('competitive_shadow_external_action_detected');

const expectedCount = Number($('Sign Shadow Observation Batch').item.json.expected_count || 0);
const inserted = Number(body.inserted_count || 0);
const duplicates = Number(body.duplicate_count || 0);
if (inserted + duplicates !== expectedCount) throw new Error('competitive_shadow_count_mismatch');
if (!Array.isArray(body.observations) || body.observations.length !== expectedCount) throw new Error('competitive_shadow_result_count_mismatch');

const expectedKeys = $('Sign Shadow Observation Batch').item.json.dedupe_keys || [];
const returnedKeys = body.observations.map((item) => String(item.dedupe_key || '')).sort();
if (JSON.stringify(expectedKeys) !== JSON.stringify(returnedKeys)) throw new Error('competitive_shadow_dedupe_key_mismatch');

return [{json:{
  shadow_verified:true,
  inserted_count:inserted,
  duplicate_count:duplicates,
  receipt_key:$('Sign Shadow Observation Batch').item.json.receipt_key
}}];
